'use strict';
(()=>{
 const prefix='abhyas-account-v1:',vault=AbhyasVault;
 let releaseLock=null,busy=false;
 let mode='login',user='',key=null,recordRaw=null,memory=null,queue=Promise.resolve(),pending=0,failed=false,closing=false;
 const screen=document.createElement('section');screen.className='account-screen';document.body.prepend(screen);
 const warning='Your account credentials and encrypted study data are stored only in this browser or app on this device. Deleting your account, clearing browser/app data, or uninstalling the app removes them. There is no Google login, cloud sync or password recovery. Keep an encrypted backup and remember your password. Exported backup files remain until you delete them separately.';
 function show(){screen.innerHTML=`<div class="account-panel"><a class="account-brand" href="#">abhyas<span aria-hidden="true"> •</span></a><p>YOUR PRIVATE STUDY SPACE</p><h1>${mode==='signup'?'A fresh beginning.':'Welcome back.'}</h1><p>${mode==='signup'?'Create an account on this device.':'Unlock your local workspace.'}</p><form id="account-form"><label for="account-user">User ID</label><input id="account-user" name="username" autocomplete="username" required minlength="3" maxlength="32" aria-describedby="username-help"><p id="username-help">3–32 letters, numbers, underscores or hyphens. Not case-sensitive.</p><label for="account-password">Password</label><input id="account-password" name="password" type="password" autocomplete="${mode==='signup'?'new-password':'current-password'}" required maxlength="128" ${mode==='signup'?'minlength="12"':''}>${mode==='signup'?'<p>12–128 characters, including uppercase, lowercase, a number and a special character.</p><label for="account-confirm">Confirm password</label><input id="account-confirm" type="password" autocomplete="new-password" required maxlength="128"><label class="account-consent"><input id="account-accept" type="checkbox" required> I understand this account is local. Deleted data needs a backup to restore, and a forgotten password cannot be reset.</label>':''}<p class="account-disclaimer"><strong>Local account warning</strong><br>${warning}</p><p id="account-message" class="account-message" role="status" aria-live="polite"></p><button class="btn primary" type="submit">${mode==='signup'?'Create local account':'Unlock workspace'}</button></form><div class="account-controls"><button id="account-switch">${mode==='signup'?'Already have an account? Log in':'New here? Create an account'}</button><button id="account-help">Forgot password?</button><label>Restore encrypted backup<input id="account-restore" type="file" accept="application/json,.json"></label></div></div>`;
 screen.querySelector('#account-switch').onclick=()=>{mode=mode==='signup'?'login':'signup';show()};screen.querySelector('#account-help').onclick=()=>message('Passwords cannot be reset locally. Encrypted backups still need the original password. If you have a plaintext study-data export, you can import that into a new account.');screen.querySelector('form').onsubmit=enter;screen.querySelector('#account-restore').onchange=restore;
 }
 async function restore(event){const file=event.target.files[0];if(!file)return;try{if(file.size>20*1024*1024)throw Error('Backup is too large.');const data=JSON.parse(await file.text());if(!/^[a-z0-9_-]{3,32}$/.test(data.user)||data.record?.version!==1||typeof data.record.salt!=='string'||typeof data.record.iv!=='string'||typeof data.record.data!=='string'||atob(data.record.salt).length!==16||atob(data.record.iv).length!==12)throw Error('Invalid encrypted backup.');if(localStorage.getItem(prefix+data.user)!==null)throw Error('This user ID already exists. Existing accounts are never overwritten by restore.');localStorage.setItem(prefix+data.user,JSON.stringify({version:1,salt:data.record.salt,iv:data.record.iv,data:data.record.data}));mode='login';show();screen.querySelector('#account-user').value=data.user;message('Backup restored. Enter its original password to unlock it.')}catch(error){message(error.message)}finally{event.target.value=''}}
 function message(text){screen.querySelector('#account-message').textContent=text}
 async function enter(event){event.preventDefault();event.stopPropagation();if(busy)return;const form=event.target;user=form.username.value.trim().toLowerCase();const password=form.password.value;if(!/^[a-z0-9_-]{3,32}$/.test(user)){message('Use 3–32 letters, numbers, underscores or hyphens for your user ID.');return}if(mode==='signup'&&(!AbhyasPassword.validPassword(password)||password!==screen.querySelector('#account-confirm').value)){message('Use all required character types and make sure both passwords match.');return}busy=true;const buttons=screen.querySelectorAll('button');buttons.forEach(b=>b.disabled=true);message('Unlocking your encrypted workspace…');try{
  if(navigator.locks){await new Promise((resolve,reject)=>{navigator.locks.request(prefix+user,{ifAvailable:true},lock=>{if(!lock){reject(Error('This account is open in another tab. Close it first.'));return}resolve();return new Promise(done=>releaseLock=done)}).catch(reject)})}
  recordRaw=localStorage.getItem(prefix+user);
  if(mode==='signup'){if(recordRaw!==null)throw Error('That user ID is already registered on this device.');const salt=vault.salt();key=await vault.key(password,salt);const sealed=await vault.seal(key,'null',user);if(localStorage.getItem(prefix+user)!==null)throw Error('That user ID was just registered. Choose another.');recordRaw=JSON.stringify({version:1,salt,...sealed});localStorage.setItem(prefix+user,recordRaw);memory=null}
  else{if(!recordRaw)throw Error('Unable to unlock. Check your user ID and password.');const record=JSON.parse(recordRaw);if(record.version!==1||atob(record.salt).length!==16||atob(record.iv).length!==12)throw Error('Invalid account');key=await vault.key(password,record.salt);memory=JSON.parse(await vault.open(key,record,user));if(memory!==null&&typeof memory!=='string')throw Error('Invalid workspace')}
  form.reset();await boot();busy=false;
 }catch(error){busy=false;releaseLock?.();releaseLock=null;key=null;message(mode==='signup'?error.message:'Unable to unlock. Check your credentials, storage access, or restore an encrypted backup if this account is damaged.');buttons.forEach(b=>b.disabled=false)}}
 function persist(raw){memory=raw;pending++;const status=document.querySelector('#vault-status');if(status)status.textContent='Encrypting changes…';queue=queue.then(async()=>{if(failed)throw Error('Previous save failed');if(localStorage.getItem(prefix+user)!==recordRaw)throw Error('Account changed in another tab');const old=JSON.parse(recordRaw),sealed=await vault.seal(key,JSON.stringify(raw),user);if(localStorage.getItem(prefix+user)!==recordRaw)throw Error('Account changed in another tab');const next=JSON.stringify({version:1,salt:old.salt,...sealed});localStorage.setItem(prefix+user,next);recordRaw=next}).catch(()=>{failed=true;const saved=document.querySelector('#note-save-state');if(saved)saved.textContent='Not saved — export a backup';document.querySelector('#vault-status').textContent='Not saved — export a backup before leaving.'}).finally(()=>{pending--;if(!failed&&!pending){const saved=document.querySelector('#note-save-state');if(saved)saved.textContent='Encrypted and saved'}if(!failed)document.querySelector('#vault-status').textContent=pending?'Encrypting changes…':'Encrypted on this device'});return queue}
 async function boot(){
  window.AbhyasStorage={getItem:()=>memory,setItem:(_,raw)=>{if(failed||closing)throw Error('Save failed');persist(raw)}};
  const bar=document.createElement('div');bar.className='account-bar';bar.innerHTML='<button id="account-migrate" hidden>Move old workspace</button><span id="vault-status">Encrypted on this device</span><button id="account-backup">Encrypted backup</button><button id="account-lock">Log out</button><button id="account-delete">Delete account</button>';document.body.append(bar);
  bar.querySelector('#account-lock').onclick=async()=>{window.AbhyasBeforeLock?.();closing=true;document.querySelector('.app-shell').inert=true;await queue;if(failed){closing=false;document.querySelector('.app-shell').inert=false;alert('Changes could not be saved. Export your study data from Settings before logging out.');return}key=null;memory=null;location.reload()};
  bar.querySelector('#account-backup').onclick=async()=>{await queue;if(failed){alert('Latest changes were not saved. Export your study data from Settings instead.');return}const blob=new Blob([JSON.stringify({user,record:JSON.parse(recordRaw)})],{type:'application/json'});if(window.AbhyasAndroid){window.AbhyasAndroid.saveFile('abhyas-encrypted-account.json',await blob.text(),'application/json');return}const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='abhyas-encrypted-account.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};
  bar.querySelector('#account-delete').onclick=async()=>{if(!confirm('Permanently delete this local account? Its saved credentials and encrypted study data will be removed from this device. Exported backups are not deleted. Export a backup first. This cannot be undone.'))return;if(prompt('Type your user ID to confirm deletion:')!==user)return;closing=true;await queue;localStorage.removeItem(prefix+user);key=null;memory=null;location.reload()};
  for(const file of ['studio.js','app.js','motion.js'])await new Promise((resolve,reject)=>{const script=document.createElement('script');script.src=file+'?v=8';script.onload=resolve;script.onerror=reject;document.head.append(script)});
  screen.remove();document.body.classList.remove('account-locked');
  const migrate=bar.querySelector('#account-migrate');migrate.hidden=!localStorage.getItem('abhyas-v1');migrate.onclick=async()=>{const legacy=localStorage.getItem('abhyas-v1');if(!legacy)return;let parsed;try{parsed=JSON.parse(legacy);if(!validBackup(parsed))throw Error()}catch{alert('The old workspace is damaged. It has been preserved unchanged.');return}if(!confirm('Move the old unencrypted workspace into this account? This replaces this account’s study data. Export its backup first. After a successful encrypted save, the old unencrypted copy will be removed.'))return;window.AbhyasBeforeLock?.();closing=true;document.querySelector('.app-shell').inert=true;await persist(legacy);if(failed){closing=false;document.querySelector('.app-shell').inert=false;return}if(localStorage.getItem('abhyas-v1')===legacy)localStorage.removeItem('abhyas-v1');location.reload()};
 }
 window.addEventListener('pageshow',e=>{if(e.persisted)location.reload()});
 window.addEventListener('beforeunload',e=>{if(pending||failed){e.preventDefault();e.returnValue=''}});
 window.addEventListener('storage',e=>{if(e.key===prefix+user||e.key===null){failed=true;if(key){alert('Your account changed or was removed in another tab. This workspace will lock.');location.reload()}}});
 if(!window.AbhyasAndroid&&'serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});
 show();
 if(!crypto.subtle){message('This device needs a secure browser with Web Crypto support to use encrypted accounts.');screen.querySelectorAll('button').forEach(b=>b.disabled=true)}
})();
